x<-readLines("stdin",warn=FALSE);n<-as.integer(x[1]);for(s in x[2:(n+1L)]){if(nchar(s)<6)cat("Your password is tai duan le.\n")else if(grepl("[^A-Za-z0-9.]",s))cat("Your password is tai luan le.\n")else if(!grepl("[A-Za-z]",s))cat("Your password needs zi mu.\n")else if(!grepl("[0-9]",s))cat("Your password needs shu zi.\n")else cat("Your password is wan mei.\n")}
